(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,46592,e=>{"use strict";e.s(["DENIALS",0,[{code:"CO-197",slug:"co-197",recover:"auth-late",title:"Prior authorization absent",official:"Precertification/authorization/notification/pre-treatment absent.",plain:"The payer required prior authorization for this service and cannot find one attached to the claim.",causes:["Authorization was never obtained because nobody checked whether the code required one","Authorization was obtained but the number was not put on the claim","The authorization covered a different CPT code than the one performed","The service went beyond the number of units or visits the authorization allowed","The authorization expired before the date of service","The rendering provider on the claim is not the one named on the authorization"],fix:["Pull the authorization record and compare four things against the claim: the CPT code, the units, the date range and the rendering provider","If a valid authorization exists and simply was not transmitted, correct the claim and resubmit rather than appealing","If the authorization covers a different code, check whether the payer allows a retro-authorization and how many days you have — the window is often as short as 72 hours after service","If it was genuinely never obtained, file a retro-authorization request with the clinical documentation showing medical necessity, and expect to lose some of these","Log the reference number and the name of the person who confirmed it, every time"],prevent:"This denial is almost entirely preventable, and in our experience it is one of the most common reasons a clean chart goes unpaid. The fix is a person who checks the authorization requirement before the visit rather than a person who discovers it afterwards.",service:"prior-authorization"},{code:"CO-16",slug:"co-16",recover:"clerical",title:"Claim lacks information or has a submission error",short:"Claim lacks information",official:"Claim/service lacks information or has submission/billing error(s).",plain:"Something on the claim is missing or malformed. On its own the code tells you nothing — the detail is in the remark code that comes with it.",causes:["A required field is blank: referring provider NPI, ordering provider, place of service","The patient demographic or member ID does not match the payer record","A required modifier is missing","Documentation the payer asked for was not attached","The taxonomy code is missing or does not match enrollment"],fix:["Read the RARC remark code attached to the denial — CO-16 alone is not actionable and the remark is where the actual reason lives","Correct the specific field and resubmit as a corrected claim, not a new one, or you will collect CO-18 duplicate denials on top","If the same remark code keeps appearing, the problem is in your claim scrubber or your registration workflow, not in the individual claim"],prevent:"CO-16 is a volume problem, not a difficulty problem. It is cheap to fix per claim and expensive in aggregate, which is exactly the kind of work that never gets done by a busy front desk.",service:"ar-calling-denial-management"},{code:"CO-29",slug:"co-29",recover:"timely",title:"Time limit for filing has expired",official:"The time limit for filing has expired.",plain:"The claim arrived after the payer’s filing deadline. This one is usually terminal, which is why it deserves attention before it happens rather than after.",causes:["The claim sat in a hold queue or a scrubber rejection nobody worked","It was originally submitted to the wrong payer and the clock kept running","Coordination of benefits was unresolved and the secondary was filed late","The practice assumed a 365 day window when the payer contract says 90"],fix:["Check whether you can prove timely submission: a clearinghouse acceptance report with a date inside the window will overturn many of these","If the delay was caused by the payer, for example an eligibility or COB error on their side, appeal with the evidence and cite it","If it was filed to the wrong payer first, many contracts allow the clock to run from the primary’s remittance date — check the contract, not the general rule","Where it is genuinely late and unprovable, write it off and move on rather than spending forty dollars of labour on it"],prevent:"Every CO-29 is a claim that was already worked once and then abandoned. An aged AR queue that nobody calls on generates these steadily and silently.",service:"ar-calling-denial-management"},{code:"CO-50",slug:"co-50",recover:"clinical",title:"Not deemed medically necessary",official:"These are non-covered services because this is not deemed a medical necessity by the payer.",plain:"The payer does not accept that the documentation supports the service. This is a clinical argument, not a clerical one.",causes:["The diagnosis submitted does not appear on the payer’s coverage policy for that CPT","The chart does not document the conservative treatment the policy requires first","Frequency limits were exceeded within the policy period","The documentation is present in the chart but was never sent"],fix:["Find the payer’s own coverage policy, the LCD or NCD for Medicare, and read what it actually requires — appeals that do not quote the policy mostly fail","Check the diagnosis first: often the service was covered and the wrong ICD-10 code was linked to it","Appeal with the specific chart sections that satisfy each policy criterion, quoted, not attached as a hundred page PDF","Where the policy requires prior conservative care, show the dates and the outcomes"],prevent:"The pattern is worth more than the individual claim. If the same CPT and diagnosis pair is being denied repeatedly, the fix is in how the visit is documented, and that is worth telling the clinician.",service:"medical-coding"},{code:"CO-45",slug:"co-45",recover:"contractual",title:"Charge exceeds the fee schedule",official:"Charge exceeds fee schedule/maximum allowable or contracted/legislated fee arrangement.",plain:"A contractual write-off rather than a denial. It only becomes a problem when the allowed amount is wrong.",causes:["Normal contractual adjustment, correct and expected","The payer loaded the wrong fee schedule for your contract","The claim was priced as out of network when you are in network","A contract escalation was agreed and never applied on the payer side"],fix:["Compare the allowed amount against your contracted rate for that CPT. If they agree, post the adjustment and move on","If the allowed amount is short, this is a payer configuration error and it is affecting every claim for that code, not just this one","Escalate underpayments as a batch with a spreadsheet of examples rather than one call per claim","Recalculate after every contract renewal, because this is when loaded rates most often go stale"],prevent:"Most practices post CO-45 automatically and never check it. Systematic underpayment hides here precisely because the code looks routine.",service:"ar-calling-denial-management"},{code:"CO-97",slug:"co-97",recover:"contractual",title:"Included in the payment for another service",short:"Payment included in another service",official:"The benefit for this service is included in the payment/allowance for another service/procedure that has already been adjudicated.",plain:"The payer is bundling this code into another one on the same claim. Sometimes that is correct and sometimes it is not.",causes:["A genuine NCCI bundling edit where the codes should not be billed together","A separately identifiable service billed without modifier 25 or modifier 59","A global surgical period the payer believes is still running","An unrelated service performed on the same day as a procedure"],fix:["Check the NCCI edit pair and whether a modifier is permitted to break it — some pairs allow it and some do not, and billing a modifier on a pair that does not allow one is a compliance problem, not a shortcut","Where modifier 25 applies, the documentation must show a separately identifiable evaluation, not just the same visit described twice","For global period denials, confirm the surgery date and whether the service was related. Modifier 24 or 79 may apply","Appeal with the operative note or the visit note, not with a letter asserting the codes are different"],prevent:"This is where coding knowledge pays for itself. The wrong answer costs the claim, and the wrong shortcut costs more than that.",service:"medical-coding"},{code:"CO-18",slug:"co-18",recover:"contractual",title:"Exact duplicate claim or service",official:"Exact duplicate claim/service (Use only with Group Code OA except where state workers' compensation regulations requires CO)",plain:"The payer already has this claim. Usually harmless, occasionally a sign that the original is stuck.",causes:["The claim was resubmitted instead of being corrected","The clearinghouse sent it twice","A legitimate repeat service on the same day was billed without a repeat modifier","Somebody rebilled because the original showed no payment, when the original was actually still in process"],fix:["Find the original claim and check its status before doing anything else — most CO-18 work is wasted because the original was fine","If a genuine repeat service was performed, resubmit with the appropriate modifier, 76 or 77, and documentation of the repeat","If the original was denied and you are resubmitting the fix, send it as a corrected claim with the original claim number, not as a fresh claim"],prevent:"A queue that rebills on a timer rather than on a status check generates these constantly, and each one buries the original.",service:"ar-calling-denial-management"},{code:"CO-22",slug:"co-22",recover:"coverage",title:"May be covered by another payer",official:"This care may be covered by another payer per coordination of benefits.",plain:"The payer thinks somebody else is primary. Until coordination of benefits is corrected on their file, nothing on this claim will pay.",causes:["The patient has other coverage the practice did not know about","The payer’s COB record is stale, often for months after a change","Medicare Secondary Payer rules apply and were not identified","A work injury or motor vehicle claim should be primary"],fix:["Call the patient before you call the payer. They can usually resolve the COB record themselves in one phone call, and the payer will not update it on your say-so","For Medicare, check the MSP record and identify which MSP category applies","Once COB is corrected, the claim usually needs resubmitting rather than reprocessing — ask which","Bill the correct primary first and attach the primary remittance when billing the secondary"],prevent:"Eligibility checked before the visit catches most of these while the patient is still in front of you, which is the only cheap moment to catch them.",service:"eligibility-verification"},{code:"CO-27",slug:"co-27",recover:"coverage",title:"Expenses incurred after coverage terminated",short:"Coverage had already ended",official:"Expenses incurred after coverage terminated.",plain:"The patient was not covered on the date of service.",causes:["The plan ended and nobody re-verified at check-in","The patient changed employer or plan at the start of the year","Coverage was retroactively terminated by the employer after the visit","Medicaid eligibility lapsed at redetermination"],fix:["Re-run eligibility for the exact date of service and keep the transaction record","If coverage was terminated retroactively after you verified it, many payers and most state Medicaid programmes will honour a documented verification — this is why keeping the eligibility record matters","If there is genuinely no coverage, check for a replacement plan before billing the patient","Check the GROUP code on the remittance before billing the patient. This denial commonly arrives as PR-27, which is patient responsibility and billable. If it arrived as CO-27 it is a contractual write-off and billing the patient breaches your contract"],prevent:"Verifying eligibility at every visit rather than at registration is dull, cheap and prevents almost all of these. It is exactly the work that gets skipped when the front desk is short-staffed.",service:"eligibility-verification"},{code:"CO-151",slug:"co-151",recover:"clinical",title:"Information does not support this many services",short:"Too many services billed",official:"Payment adjusted because the payer deems the information submitted does not support this many/frequency of services.",plain:"The payer accepts the service but not the quantity or the frequency at which it was billed.",causes:["Units billed per level where the payer pays per region or per session","Frequency limits in the payer policy exceeded within a rolling period","The documentation does not support the number of units on the claim","A time-based code billed without the time documented"],fix:["Check the payer policy for the frequency limit and the period it runs over — a rolling twelve months and a calendar year are different things and practices lose money on that distinction","For time-based codes, confirm the chart records start and stop times, not just a total","If the units are correct and documented, appeal with the specific chart evidence for each unit","If the units were wrong, correct them and resubmit rather than appealing"],prevent:"Frequency-limited services need tracking at scheduling, not at billing. By the time the denial arrives the service has already been given away.",service:"medical-coding"},{code:"CO-109",slug:"co-109",recover:"coverage",title:"Not covered by this payer or contractor",short:"Wrong payer or contractor",official:"Claim/service not covered by this payer/contractor. You must send the claim/service to the correct payer/contractor.",plain:"It went to the wrong place.",causes:["Wrong payer ID or wrong Medicare Administrative Contractor","The patient has moved to a Medicare Advantage plan and the claim went to traditional Medicare","A Medicaid managed care plan was billed as straight Medicaid, or the reverse","The service belongs under a carved-out benefit administered by somebody else"],fix:["Re-verify eligibility and read which plan is actually active, including the plan type, not just whether coverage exists","Watch the filing clock: time spent at the wrong payer usually still counts, so this one turns into CO-29 if it sits","Rebill to the correct payer immediately and note the original submission date in case timely filing becomes an argument"],prevent:"Medicare Advantage enrollment changes are, in our experience, the most common version of this and they cluster in January. A practice that re-verifies in January prevents most of a year’s worth.",service:"eligibility-verification"},{code:"CO-B7",slug:"co-b7",recover:"enrollment",title:"Provider not certified or eligible on this date",short:"Provider not eligible that day",official:"This provider was not certified/eligible to be paid for this procedure/service on this date of service.",plain:"A credentialing or enrollment problem rather than a claim problem: nothing this provider bills to this payer will pay until it is fixed, and it is rarely one claim.",causes:["Enrollment lapsed at revalidation and nobody tracked the deadline","The provider was never enrolled with this payer or this plan","A new provider started seeing patients before enrollment completed","The group or location on the claim is not linked to the provider’s enrollment","PECOS or CAQH information went stale and the payer suspended the record"],fix:["Establish the effective date of the enrollment before touching the claims — that date tells you which claims are recoverable","Many payers allow retroactive enrollment for a limited window, often 30 to 90 days. Ask specifically for retroactive effective dating and get the answer in writing","Hold the affected claims rather than resubmitting them repeatedly; every rebill against a bad enrollment is wasted work","Once the enrollment is corrected, resubmit the held claims as a batch"],prevent:"This is the most expensive denial on this list because it is never one claim. A revalidation deadline missed by a week can stop payment on every claim behind it, and the recovery window is measured in weeks.",service:"credentialing"},{code:"CO-4",slug:"co-4",recover:"clerical",title:"Procedure code inconsistent with the modifier",short:"Modifier and code disagree",official:"The procedure code is inconsistent with the modifier used.",plain:"The code and the modifier disagree, or a modifier the payer required was not there.",causes:["A required modifier was omitted — 25, 59, 26, TC and the LT/RT pair are the usual suspects","A modifier was appended that the code does not accept","Laterality billed without LT, RT or the 50 bilateral modifier","A professional or technical component billed without 26 or TC on a code that is split","Modifier order wrong on a claim where the payer reads only the first two"],fix:["Read the RARC alongside it — CO-4 rarely tells you which modifier without one","Check the code against the payer policy rather than against general CPT guidance; payers differ on which modifiers they accept","For bilateral work, confirm whether the payer wants modifier 50 on one line or LT and RT on two — billing the wrong convention produces this denial repeatedly","Correct and resubmit as a corrected claim, not as a new one"],prevent:"This is a scrubber problem more than a knowledge problem. If the same code and modifier pair fails twice, the rule belongs in the claim edit rather than in somebody’s memory.",service:"medical-coding"},{code:"CO-11",slug:"co-11",recover:"clerical",title:"Diagnosis inconsistent with the procedure",short:"Diagnosis and procedure disagree",official:"The diagnosis is inconsistent with the procedure.",plain:"The payer does not accept that the diagnosis submitted justifies the procedure performed.",causes:["The linked diagnosis pointer references the wrong ICD-10 code on a multi-diagnosis claim","A symptom code was used where the payer policy requires a definitive diagnosis","The diagnosis is valid clinically but is not on the payer’s covered list for that CPT","Laterality mismatch — a right-side procedure against a left-side diagnosis","The claim carries the diagnosis for a different encounter entirely"],fix:["Check the diagnosis pointers first. On a claim with four diagnoses, the wrong pointer is a frequent cause and it is a clerical fix","Pull the payer’s coverage policy and read the accepted diagnosis list for that CPT","Where the chart supports a more specific code, recode from the documentation rather than choosing a code that happens to be on the list","Correct and resubmit; appeal only where the documentation genuinely supports the pairing"],prevent:"Never pick a diagnosis because it gets a claim paid. Recode from what the chart says, and if the chart does not support a covered diagnosis, the conversation belongs with the clinician.",service:"medical-coding"},{code:"CO-96",slug:"co-96",recover:"clinical",title:"Non-covered charges",official:"Non-covered charge(s). At least one Remark Code must be provided (may be comprised of either the NCPDP Reject Reason Code, or Remittance Advice Remark Code that is not an ALERT.)",plain:"The plan does not cover this service at all. Distinct from medical necessity, which is an argument about evidence.",causes:["The service is genuinely excluded from the plan — cosmetic, experimental, or outside the benefit","The service is covered but was billed under a code the plan excludes","A carved-out benefit administered by a different organization entirely","Statutory exclusion under Medicare, which no appeal will overturn"],fix:["Read the RARC. CO-96 alone does not distinguish an exclusion from a coding problem, and those have opposite remedies","Confirm whether an Advance Beneficiary Notice was obtained. Without one you generally cannot bill a Medicare patient for a statutorily excluded service","If it is a carve-out, find the administering organization and rebill there — this is often behavioral health, dental or vision","Read the GROUP code before doing anything with the balance. PR-96 is patient responsibility and billable; CO-96 is a contractual write-off and is not. The same CARC arrives under either group depending on the payer and the reason"],prevent:"Eligibility verification that records the plan type, not merely that coverage is active, catches most of these before the visit.",service:"eligibility-verification"},{code:"CO-119",slug:"co-119",recover:"coverage",title:"Benefit maximum reached",short:"Benefit maximum reached",official:"Benefit maximum for this time period or occurrence has been reached.",plain:"The patient has used up what the plan allows for this benefit in this period.",causes:["Annual or lifetime visit caps exhausted — common in therapy, chiropractic and behavioral health","A dollar maximum on a benefit category reached","Units consumed by another provider the practice did not know about","Plan year reset date assumed to be January when the plan runs on a different cycle"],fix:["Confirm the remaining benefit directly with the payer and record the number and the date checked","Check whether an authorization for additional visits is available on medical necessity — many plans allow an extension that the initial cap does not mention","Only move the balance to the patient if the remittance shows the PR group code and a signed acknowledgement exists. A CO-grouped denial is a contractual write-off whatever the acknowledgement says"],prevent:"Benefit counters need tracking at scheduling. By the time the denial arrives the service has already been delivered and the money is gone.",service:"eligibility-verification"},{code:"CO-140",slug:"co-140",recover:"clerical",title:"Patient identification number and name do not match",short:"Member ID and name disagree",official:"Patient/Insured health identification number and name do not match.",plain:"The member ID and the name on the claim disagree with the payer’s record.",causes:["A transposed digit in the member ID at registration","A married or maiden name mismatch against the payer file","The subscriber billed as the patient, or the reverse, on a dependent claim","Suffix handling — Jr, Sr or III present on one record and not the other"],fix:["Re-run eligibility and copy the name and ID exactly as the payer returns them, not as the patient wrote them on the form","On dependent claims, confirm the subscriber and patient fields are the right way round","Correct and resubmit — this is never an appeal"],prevent:"Capturing the payer’s own spelling at eligibility rather than the patient’s handwriting removes almost all of these, and it costs nothing.",service:"eligibility-verification"},{code:"CO-170",slug:"co-170",recover:"clinical",title:"Payment denied for this provider type",short:"Provider type not paid",official:"Payment is denied when performed/billed by this type of provider.",plain:"The service may be covered, but not when delivered or billed by a provider of this type.",causes:["The rendering provider’s taxonomy does not permit this service under the plan","Incident-to billing requirements not met for a mid-level provider","Supervising physician not identified where the payer requires one","A facility service billed on a professional claim or the reverse"],fix:["Confirm the taxonomy code on the claim matches the provider’s actual enrollment, not merely their credential","For mid-level providers, check the payer’s incident-to rules — several require the physician to be on site and to have initiated the plan of care","Where the service should have been billed under the supervising physician, correct and resubmit rather than appealing"],prevent:"This is a credentialing question wearing a billing costume. If a provider type is generating these repeatedly, the enrollment record is what needs fixing.",service:"credentialing"},{code:"CO-234",slug:"co-234",recover:"clinical",title:"Procedure not paid separately",short:"Not paid separately",official:"This procedure is not paid separately. At least one Remark Code must be provided (may be comprised of either the NCPDP Reject Reason Code, or Remittance Advice Remark Code that is not an ALERT.)",plain:"The payer treats this service as part of another one, similar to CO-97 but usually driven by the fee schedule rather than an NCCI edit.",causes:["A service bundled into the global fee for the primary procedure","An add-on code billed without its primary code","Supplies or drugs the payer considers included in the procedure payment","A code with a status indicator making it never separately payable"],fix:["Check the status indicator on the fee schedule before appealing — some codes are never separately payable and an appeal simply wastes labour","For add-on codes, confirm the primary procedure was billed and paid on the same claim","Where the service was genuinely distinct, the argument is the same as CO-97: documentation showing separate identifiable work"],prevent:"Knowing which of your common codes are never separately payable stops the practice billing them and stops staff appealing them. Both are quiet, recurring costs.",service:"medical-coding"},{code:"CO-252",slug:"co-252",recover:"supply",title:"Additional documentation required",official:"An attachment/other documentation is required to adjudicate this claim/service. At least one Remark Code must be provided (may be comprised of either the NCPDP Reject Reason Code, or Remittance Advice Remark Code that is not an ALERT).",plain:"The payer will not decide until it sees paperwork. Nothing happens until it arrives.",causes:["Operative note, medical records or an itemised bill requested and not sent","An unlisted or miscellaneous code billed without a description","Modifier 22 billed without documentation of the additional work","A previous request that went to a fax number nobody monitors"],fix:["Read the RARC for exactly what is wanted — sending everything is slower than sending the right thing and often triggers a fresh review","Send by the method the payer specifies. A portal upload with a confirmation number is worth far more than a fax with no receipt","Record the submission date and the reference number, because these frequently need chasing twice","Watch the timely filing clock: a claim waiting on documentation is still ageing"],prevent:"If particular codes generate this every time, attach the documentation on first submission rather than waiting to be asked. It converts a sixty-day cycle into a clean claim.",service:"ar-calling-denial-management"},{code:"CO-198",slug:"co-198",recover:"supply",title:"Prior authorization exceeded",short:"Authorization limit exceeded",official:"Precertification/notification/authorization/pre-treatment exceeded.",plain:"An authorization exists. The problem is that you went past what it allowed — more units, more visits, or a longer date range than was approved.",causes:["The approved unit or visit count was used up and treatment continued","Services were rendered after the authorization date range ended","The authorization covered a lower level of service than the one performed","A second course of treatment was billed against the first authorization","Nobody was tracking the remaining balance on the authorization while the patient was still in treatment"],fix:["Pull the authorization and count exactly what was approved against exactly what was billed — units, visits and date range, separately","Bill the portion that falls inside the authorization and handle the excess separately, rather than appealing the whole claim","For the excess, request an extension or retro-authorization with the clinical notes that justify why treatment continued","Where the payer allows it, ask for the extension BEFORE the last approved visit rather than after — several will not backdate at all"],prevent:"This is a tracking failure, not a knowledge failure. Somebody has to hold the remaining balance on every open authorization and flag it before the last visit, which is exactly the job a prior authorization seat does.",service:"prior-authorization"},{code:"CO-288",slug:"co-288",recover:"contractual",title:"Referral absent",short:"Referral absent",official:"Referral absent",plain:"The plan required a referral from the patient’s primary care physician and there is not one on file for this visit.",causes:["The patient is on an HMO or point-of-service plan that requires a PCP referral and nobody checked","A referral existed but expired, or covered a different number of visits","The referral names a different specialist or a different practice than the one that billed","The referral was obtained after the date of service and the plan does not accept it retroactively"],fix:["Check eligibility again and confirm whether the plan is referral-required — the answer differs by product line within the same payer","If a valid referral exists, get the referral number onto the claim and resubmit rather than appealing","If none exists, contact the PCP office; some will issue one covering the date of service, many will not","Where the patient self-referred, the balance may be theirs, but check the plan documents before transferring it"],prevent:"Referral status is an eligibility question and belongs in the same check as coverage and benefits, before the visit. Found afterwards it is often unrecoverable.",service:"referral-management"},{code:"PR-204",slug:"pr-204",recover:"contractual",title:"Not covered under the patient’s current plan",short:"Not covered by this plan",official:"This service/equipment/drug is not covered under the patient’s current benefit plan",plain:"The service itself is excluded from this particular plan. This is a benefit design decision, not a coding error.",causes:["The plan genuinely excludes the service — cosmetic, investigational, or outside the benefit category","The patient changed plans and the new one has a narrower benefit set","The service is covered under a different benefit (pharmacy rather than medical, or vice versa) and was billed to the wrong one","A plan-specific exclusion applies that the general payer policy does not mention"],fix:["Read the benefit exclusion in the plan document rather than the payer’s general policy — this is a plan-level determination","Check whether the service should have been billed under a different benefit, which is the most commonly recoverable version of this denial","If genuinely excluded, this becomes patient responsibility — but only if the patient was told beforehand","Where an advance beneficiary notice or financial responsibility form was signed, bill the patient with the appropriate modifier; where it was not, that conversation is now much harder"],prevent:"The recoverable part of this denial is entirely upstream: eligibility and benefits checked against the specific plan before the visit, and a signed financial responsibility form when a service is likely to be excluded.",service:"eligibility-verification"},{code:"OA-23",slug:"oa-23",recover:"contractual",title:"Prior payer’s adjudication",short:"Prior payer already adjudicated",official:"The impact of prior payer(s) adjudication including payments and/or adjustments. (Use only with Group Code OA)",plain:"This is a coordination of benefits adjustment on a secondary claim. It reflects what the primary payer already did rather than a problem with your claim.",causes:["Normal secondary processing — the secondary is accounting for the primary’s payment and adjustments","The primary’s explanation of benefits was transmitted incorrectly, so the secondary calculated from the wrong numbers","Primary and secondary were applied in the wrong order","The primary’s contractual adjustment was reported as a payment or vice versa"],fix:["Confirm this is genuinely a secondary claim and that the payer order is correct before doing anything else","Compare the primary EOB line by line against what was transmitted to the secondary — the loop 2320 and 2430 amounts are where this usually goes wrong","Where the amounts match and the balance is zero, this is not a denial and needs no work; posting it as one wastes an AR caller’s day","Where they do not match, correct the COB information and resubmit rather than appealing"],prevent:"Most OA-23 lines are correct and need nothing. The discipline worth having is telling those apart from the ones that are wrong, which means posting remittances line by line rather than in bulk.",service:"payment-posting"},{code:"CO-185",slug:"co-185",recover:"enrollment",title:"Rendering provider not eligible",short:"Rendering provider not eligible",official:"The rendering provider is not eligible to perform the service billed.",plain:"The payer does not accept this provider as eligible for this service — an enrollment, credentialing or scope-of-practice problem rather than a coding one.",causes:["The provider is not credentialed with this payer, or the credentialing has lapsed","The provider is enrolled but not for this plan or product line","The service is outside what the payer allows for that provider’s type or taxonomy","A supervising physician was required and the claim does not show one","The provider’s enrollment was deactivated — often after a missed Medicare revalidation"],fix:["Check the provider’s enrollment status with that specific payer and product, not just their license","For Medicare, check whether billing privileges were deactivated and when — that changes the whole answer","If credentialing is in progress, find out whether the payer backdates to the application date; some do, most do not","Where a supervising provider was required, correct the claim to show them rather than appealing"],prevent:"This denial is a calendar problem wearing a coding costume. Revalidation dates, re-credentialing intervals and CAQH attestation all have to be tracked, which is the whole job of a credentialing seat.",service:"credentialing"},{code:"CO-8",slug:"co-8",recover:"enrollment",title:"Procedure inconsistent with provider type",short:"Procedure and provider type disagree",official:"The procedure code is inconsistent with the provider type/specialty (taxonomy).",plain:"The payer does not expect a provider of this specialty to bill this code, based on the taxonomy attached to the claim.",causes:["The taxonomy code on the claim is wrong or out of date","The taxonomy in NPPES does not match the one the payer has on the enrollment record","The provider genuinely is not permitted to bill this code under that specialty","A group taxonomy was sent where an individual one was needed"],fix:["Compare the taxonomy on the claim against NPPES and against the payer’s enrollment record — all three have to agree","Correct and resubmit where it is a transmission problem, which is most of the time","Where the payer’s record is out of date, updating NPPES alone will not fix it; the enrollment record is separate and has to be updated too","Where the restriction is real, check whether another provider in the practice can appropriately render and bill it"],prevent:"Taxonomy sits in three systems that drift apart silently. Reconciling them once, and again whenever a provider changes specialty or joins, prevents an entire class of denial.",service:"credentialing"},{code:"CO-236",slug:"co-236",recover:"clinical",title:"Procedure/modifier combination not compatible",short:"Modifier combination not allowed",official:"This procedure or procedure/modifier combination is not compatible with another procedure or procedure/modifier combination provided on the same day according to the National Correct Coding Initiative or workers compensation state regulations/ fee schedule requirements.",plain:"Two things billed on the same day conflict under NCCI edits or a state fee schedule. The pair is the problem, not either code alone.",causes:["An NCCI procedure-to-procedure edit applies and no modifier was appended","A modifier was appended but the edit does not permit a modifier to override it","The modifier used does not fit the clinical circumstance being claimed","A workers compensation state fee schedule imposes its own combination rule that differs from NCCI"],fix:["Look up the specific pair in the NCCI edit tables and read the modifier indicator: 0 means no modifier will ever override it, 1 means a modifier may be allowed with documentation","Where the indicator is 0, appealing is not the route; the pair cannot be billed together","Where it is 1, confirm the documentation genuinely supports a separate and distinct service before appending a modifier","For workers compensation, check the state fee schedule as well — it can be stricter than NCCI"],prevent:"The edit tables are published and updated quarterly. Scrubbing against the current quarter before submission turns this denial into a pre-submission correction, which costs minutes instead of weeks.",service:"medical-coding"},{code:"CO-231",slug:"co-231",recover:"clinical",title:"Mutually exclusive procedures",short:"Mutually exclusive procedures",official:"Mutually exclusive procedures cannot be done in the same day/setting.",plain:"The two procedures billed cannot clinically or by rule both have happened at the same encounter.",causes:["Two codes describe alternative approaches to the same thing and both were billed","A comprehensive code and a component of it were both billed","A bilateral procedure was billed as two unilateral lines where the payer expects one line with a modifier","Charge entry duplicated a line that should have been a units increase"],fix:["Read the operative or encounter note and decide which code actually describes what was done","Where both genuinely happened at separate sites or sessions, the documentation must say so explicitly before a modifier is defensible","Where it is a bilateral billing convention problem, rebill in the format that payer expects rather than appealing","Where charge entry duplicated a line, correct and resubmit"],prevent:"Mutually exclusive pairs are published in the same NCCI tables as the CO-236 edits. A scrub that checks both catches this before it leaves the building.",service:"medical-coding"},{code:"CO-107",slug:"co-107",recover:"enrollment",title:"Related or qualifying claim not identified",short:"Qualifying claim not identified",official:"The related or qualifying claim/service was not identified on this claim.",plain:"This service only pays when it is linked to another one, and the link is missing from the claim.",causes:["An add-on code was billed without its primary procedure on the claim","The primary procedure was billed on a separate claim, so the payer cannot see the pair","The qualifying service was performed by another provider and no reference was included","An assistant surgeon or co-surgeon line has no corresponding primary surgical line"],fix:["Identify what the qualifying service is — the code descriptor for an add-on code names its primary explicitly","Where both were performed, rebill them together on one claim rather than appealing separately","Where the primary was billed on an earlier claim, submit with the reference to it that the payer requires","Where no qualifying service exists, the add-on code should not have been billed at all"],prevent:"Add-on codes should never leave the practice unaccompanied. A scrubber rule that refuses to submit one without its primary removes this denial almost entirely.",service:"charge-entry"},{code:"PR-31",slug:"pr-31",recover:"coverage",title:"Patient cannot be identified as our insured",short:"Patient not found as insured",official:"Patient cannot be identified as our insured.",plain:"The payer cannot match the patient to a member record. Usually a demographic or identifier mismatch rather than a coverage lapse.",causes:["Member ID entered incorrectly, or missing a prefix the payer requires","Name spelled differently from the member record, or a married name not yet updated with the plan","Date of birth transposed","The claim went to the wrong payer, or to the wrong plan within a large payer","The patient is covered as a dependent under a subscriber whose details were not captured"],fix:["Re-run eligibility with the details exactly as they appear on the card, then compare against what was billed","Check the subscriber rather than the patient where the patient is a dependent — the ID belongs to the subscriber","Where the payer routing is wrong, identify the correct payer ID and resubmit rather than appealing","Correct and resubmit; this is a correctable claim, not a denial to argue with"],prevent:"Copy the card at every visit, not just the first, and re-verify eligibility each time. Almost every PR-31 traces back to a detail that was right once and changed.",service:"eligibility-verification"},{code:"CO-286",slug:"co-286",recover:"contractual",title:"Appeal time limits not met",short:"Appeal filed too late",official:"Appeal time limits not met.",plain:"The appeal arrived after the payer’s deadline. The clock for appealing is separate from, and usually shorter than, the clock for filing.",causes:["The appeal window was counted from the wrong date — it usually runs from the remittance date, not the date of service","The denial sat in a work queue while the window ran out","A first-level appeal was filed in time but the second level was not","The payer’s window for that plan is shorter than the one the biller assumed"],fix:["Check the plan’s actual appeal window and what date it runs from before conceding — they differ by payer and by product","Where there is good cause provision, file with the evidence of it; some payers accept documented submission attempts","Where the deadline is genuinely missed, this money is gone and the useful work is stopping the next one","Do not resubmit as a new claim to restart a clock — that is a timely filing problem, not an appeal, and payers detect it"],prevent:"Every denial needs a date stamp and a deadline the day it lands, and the queue has to be worked oldest first. A denial nobody touched for 90 days is a decision to write it off, made by accident.",service:"ar-calling-denial-management"},{code:"PR-1",slug:"pr-1",recover:"contractual",title:"Deductible amount",official:"Deductible Amount",plain:"The payer applied this amount to the patient’s deductible. It is not a denial — it is the plan working as designed, and the balance is the patient’s.",causes:["The patient has not met their deductible for the plan year","A high-deductible plan where most early-year services fall to the patient","The deductible reset at the plan year boundary, which is not always 1 January","Services applied to a separate deductible for a specific benefit category"],fix:["Do not appeal this. Confirm the amount is right against the plan’s deductible and what has already been applied","Move the balance to patient responsibility and get a statement out promptly — collection rates fall sharply with age","Where the patient has other coverage, this is where the secondary claim goes","Where the deductible appears already met, that is worth a call; the payer’s accumulator can be behind"],prevent:"The prevention here is financial, not clerical: check the remaining deductible during eligibility and tell the patient what they will owe before the visit. A balance discussed in advance is collected far more often than one that arrives as a surprise.",service:"patient-billing"},{code:"CO-5",slug:"co-5",recover:"clerical",title:"Procedure inconsistent with place of service",short:"Wrong place of service",official:"The procedure code/type of bill is inconsistent with the place of service.",plain:"The code you billed is not one the payer accepts for the setting the service happened in.",causes:["Place of service left at the practice default when the visit happened somewhere else","Telehealth billed with an office place of service, or the reverse, under a rule that changed","A facility-only procedure billed with an office place of service","Hospital-based provider billing under an office setting"],fix:["Check the encounter for where the service actually happened, not where the provider usually works.","Confirm the payer’s current place-of-service rule for that code — telehealth rules in particular have changed repeatedly.","Correct the place of service and resubmit as a corrected claim rather than a new one.","If the place of service was right, appeal with the encounter documentation showing the setting."],prevent:"Set place of service from the schedule rather than from a default, and audit telehealth claims separately after any payer policy change.",service:"charge-entry"},{code:"CO-9",slug:"co-9",recover:"clerical",title:"Diagnosis inconsistent with patient age",short:"Diagnosis and age disagree",official:"The diagnosis is inconsistent with the patient’s age.",plain:"The diagnosis code you sent is one the payer only accepts for a different age group.",causes:["Date of birth wrong in registration","An age-specific code used outside its age range — newborn, paediatric or geriatric codes are the common ones","A code selected from a favourites list without checking the age qualifier","Wrong patient selected at charge entry"],fix:["Check the date of birth on the claim against the payer’s record and the chart. A registration typo is, in our experience, the most common cause.","Read the ICD-10 Tabular entry for the code — age restrictions are stated there.","Correct whichever is wrong and resubmit corrected.","If both the age and the code are right, appeal with the documentation supporting the diagnosis."],prevent:"Verify date of birth against the payer at eligibility rather than trusting the demographic on file, and remove age-specific codes from general favourites lists.",service:"eligibility-verification"},{code:"CO-10",slug:"co-10",recover:"clerical",title:"Diagnosis inconsistent with patient gender",short:"Diagnosis and gender disagree",official:"The diagnosis is inconsistent with the patient’s gender.",plain:"The diagnosis code is one the payer only accepts for a different gender marker than the one on the claim.",causes:["Gender marker in registration does not match the payer’s record","A gender-specific diagnosis code billed for a patient whose recorded marker differs","Wrong patient selected at charge entry","Payer record not updated after the patient updated it with the practice"],fix:["Compare the gender marker on the claim with the payer’s record at eligibility — the mismatch is usually between systems rather than in the coding.","Where the service was clinically appropriate, appeal with documentation rather than changing a code to make a claim pay.","Where a payer requires a specific condition indicator for this situation, apply it per that payer’s current guidance.","Never alter a patient’s recorded gender to clear a denial. It is a record change, not a billing fix."],prevent:"Reconcile demographics with the payer at eligibility, and treat this denial as a data-matching problem first and a coding problem second.",service:"eligibility-verification"},{code:"CO-15",slug:"co-15",recover:"auth-late",title:"Authorization number missing or invalid",short:"Authorization number missing",official:"The authorization number is missing, invalid, or does not apply to the billed services or provider.",plain:"There is an authorization requirement here, and the number you sent is absent, wrong, or does not cover what was billed.",causes:["Authorization obtained but never entered on the claim","Number transposed at charge entry","Authorization covers a different code, a different provider, or a different date range than the service","Units billed exceed the units authorized"],fix:["Pull the authorization and compare four things against the claim: code, provider, date range and units. One of them will not match.","If it is a data entry problem, correct and resubmit as a corrected claim.","If the authorization genuinely does not cover the service, ask the payer whether a retro-authorization is possible and on what timeline.","Log the authorization number, expiry and unit count on the account so the next claim in the course does not repeat it."],prevent:"Record the authorized code, provider, date range and unit count at the time it is granted, and check the remaining units before each subsequent visit rather than at the end.",service:"prior-authorization"},{code:"CO-24",slug:"co-24",recover:"coverage",title:"Charges covered under a capitation agreement",short:"Covered under capitation",official:"Charges are covered under a capitation agreement/managed care plan.",plain:"The payer says this service is included in a capitated arrangement, so there is no separate fee-for-service payment.",causes:["Patient enrolled in a managed care plan the practice did not know about","Claim sent to the wrong entity — the plan rather than the capitated group, or the reverse","The service genuinely falls inside a capitation arrangement the practice holds","Eligibility check did not surface the managed care assignment"],fix:["Check eligibility for the date of service and identify which entity carries the risk.","If the patient is assigned to a capitated group, bill that group under its own process rather than resubmitting to the payer.","If the practice holds the capitation, the balance is not billable and belongs in a contractual adjustment — read the group code before moving anything.","If the assignment is wrong, escalate to the payer’s provider relations with the eligibility record."],prevent:"Check managed care assignment at eligibility, not just active coverage. Assignment changes monthly and is invisible on a card.",service:"eligibility-verification"},{code:"CO-32",slug:"co-32",recover:"coverage",title:"Patient is not an eligible dependent",short:"Not an eligible dependent",official:"Our records indicate the patient is not an eligible dependent.",plain:"The payer does not recognize this patient as a covered dependent on the subscriber’s policy.",causes:["Dependent aged off the policy","Dependent never added, or added after the date of service","Wrong subscriber linked to the patient","Divorce, custody or employment change altering the policy"],fix:["Run eligibility for the date of service and confirm what the payer holds — not what the family described.","If there is other coverage, rebill the correct payer inside its filing window.","If the dependent was added retroactively, resubmit after the payer’s system reflects it and reference the enrollment date.","If there genuinely was no coverage, the balance moves to the patient — but check the group code before moving it."],prevent:"Verify dependent eligibility at every visit for patients near an age threshold, and re-verify after any reported family or employment change.",service:"eligibility-verification"},{code:"CO-33",slug:"co-33",recover:"coverage",title:"Insured has no dependent coverage",short:"No dependent coverage",official:"Insured has no dependent coverage.",plain:"The subscriber’s policy covers the subscriber only, so a dependent’s claim has nothing to pay against.",causes:["Employee-only plan billed for a spouse or child","Dependent coverage elected but not effective on the date of service","Claim sent under the wrong family member’s policy","A second parent’s policy is the correct one and was not identified"],fix:["Confirm the policy type at eligibility — employee-only is stated there and is not visible on a card.","Ask the family whether other coverage exists; a second parent’s policy is the usual answer.","Rebill the correct payer inside its timely filing window.","If no coverage exists for the dependent, the balance is patient responsibility — subject to the group code on the remittance."],prevent:"Capture coverage type as well as coverage at registration, and ask about a second policy whenever the patient is a child.",service:"eligibility-verification"},{code:"CO-35",slug:"co-35",recover:"coverage",title:"Lifetime benefit maximum reached",short:"Lifetime maximum reached",official:"Lifetime benefit maximum has been reached.",plain:"The policy has a lifetime cap on this benefit and the patient has used it.",causes:["A benefit with a lifetime cap — most commonly seen on specific services rather than on medical coverage generally","Prior treatment elsewhere counted against the same maximum","Benefit accumulator not checked before an extended course of treatment"],fix:["Confirm the maximum and the amount used with the payer, and get it in writing where the benefit is expensive.","Check whether the patient has secondary coverage that carries the benefit.","Tell the patient before the next service rather than after it — this is a benefit exhaustion, not a billing error, and it will keep denying.","Read the group code before moving the balance to the patient."],prevent:"Check benefit accumulators, not just active coverage, before starting any extended or high-cost course of treatment.",service:"eligibility-verification"},{code:"CO-39",slug:"co-39",recover:"auth-late",title:"Services denied at the time authorization was requested",short:"Authorization already refused",official:"Services denied at the time authorization/pre-certification was requested.",plain:"The authorization was asked for and refused, and the service was delivered anyway.",causes:["Authorization denied and the denial not communicated to scheduling before the visit","The appeal of the authorization denial was never filed","Service delivered on clinical urgency without the payer agreeing it was urgent","Peer-to-peer review offered and not taken up inside the window"],fix:["Find the authorization denial and read why it was refused — the reason decides whether an appeal has anything to work with.","Check whether a peer-to-peer review window is still open. It usually closes fast and is the strongest route.","Appeal with clinical documentation addressing the specific refusal reason, not with a general medical necessity letter.","If the service was genuinely urgent, appeal on that basis with the record supporting urgency."],prevent:"A refused authorization must reach scheduling before the appointment. This denial is almost always a communication failure inside the practice rather than a payer problem.",service:"prior-authorization"},{code:"CO-136",slug:"co-136",recover:"coverage",title:"Failure to follow the prior payer’s coverage rules",short:"Prior payer's rules not followed",official:"Failure to follow prior payer's coverage rules. (Use only with Group Code OA)",plain:"This is a secondary claim, and the secondary payer says the primary’s rules were not followed before it reached them.",causes:["Primary payer’s requirements — authorization, referral, network — not met","Claim sent to the secondary before the primary adjudicated it","Primary remittance not attached or not readable","Coordination of benefits order wrong"],fix:["Confirm the order of benefits with both payers before doing anything else.","Resolve the primary’s issue first — the secondary will not pay around it.","Resubmit to the secondary with the primary’s remittance attached in the format that payer accepts.","Where the primary genuinely denied for its own reason, appeal there rather than pursuing the secondary."],prevent:"Never bill a secondary before the primary has adjudicated, and record the order of benefits on the account rather than deducing it each time.",service:"ar-calling-denial-management"},{code:"CO-150",slug:"co-150",recover:"clinical",title:"Information does not support this level of service",short:"Level of service unsupported",official:"Payer deems the information submitted does not support this level of service.",plain:"The payer accepts the visit happened but not at the level you billed — usually an E/M downcode.",causes:["Documentation does not support the medical decision making or time claimed","A high-level code billed routinely for a presentation that does not support it","Time-based billing without the time and its content documented","Payer applying an automated levelling edit against its own norms"],fix:["Read the note against the level billed before appealing — if the documentation does not support it, an appeal will not create support.","Where it does, appeal with the note and a short statement mapping the documentation to the level’s requirements.","Where a payer downcodes systematically across a provider, that is a pattern worth escalating to provider relations with data.","Where the documentation is genuinely thin, this is a documentation conversation with the provider, not a billing one."],prevent:"Audit a sample of high-level visits against documentation quarterly. A provider levelling consistently above their documentation will be found by the payer eventually, and it is much better to find it first.",service:"medical-coding"},{code:"CO-167",slug:"co-167",recover:"clinical",title:"Diagnosis is not covered",official:"This (these) diagnosis(es) is (are) not covered.",plain:"The payer does not cover the condition you billed, whatever the procedure was.",causes:["A diagnosis excluded from the plan — cosmetic, experimental or a specific carve-out","The most specific supporting diagnosis not sequenced first","A screening diagnosis where the plan covers only diagnostic indications, or the reverse","Coverage governed by a local or national coverage determination the diagnosis does not meet"],fix:["Read the payer’s coverage policy for the procedure and find the diagnosis list it accepts.","Check the chart for a covered diagnosis that the provider addressed and that was not sequenced first — do not add a diagnosis the note does not support.","Where the note supports a covered indication, correct the sequencing and resubmit corrected.","Where the condition genuinely is not covered, an advance beneficiary notice or a financial conversation is the right route, not a resubmission."],prevent:"Where a procedure has a coverage policy with a diagnosis list, check it before the service. Afterwards the only options are appeal or write-off.",service:"medical-coding"},{code:"CO-177",slug:"co-177",recover:"coverage",title:"Patient has not met eligibility requirements",short:"Eligibility not met",official:"Patient has not met the required eligibility requirements.",plain:"There is coverage, but the patient has not satisfied a condition the plan attaches to it.",causes:["Waiting period not served","Premium unpaid and the policy in a grace or suspended status","A plan requirement — a health assessment, a programme enrollment — not completed","Coverage effective after the date of service"],fix:["Ring the payer and get the specific requirement that was not met and the date it will be, if it will be.","If the requirement will be satisfied and the claim can be resubmitted after, diary it inside the filing window.","If the policy lapsed for non-payment, find out whether a grace period applies and what happens to claims inside it.","Read the group code before moving anything to the patient."],prevent:"At eligibility, capture effective dates and plan status, not just whether coverage exists. Active is not the same as payable.",service:"eligibility-verification"},{code:"CO-181",slug:"co-181",recover:"clerical",title:"Procedure code invalid on the date of service",short:"Code invalid on that date",official:"Procedure code was invalid on the date of service.",plain:"The code existed at some point but was not valid on the day the service happened.",causes:["Annual code set update — the code was deleted or replaced effective 1 January","A new code billed for a date before its effective date","A code from a superseded local list still in a favourites list or a charge master","Back-dated claim billed with the current year’s code"],fix:["Look the code up against the code set in force on the date of service, not today’s.","Find the replacement code and its effective date, then resubmit corrected.","Check whether the same stale code sits in the charge master or a favourites list — if it does, every claim using it is denying.","Where the claim is old, check the timely filing window before spending effort on it."],prevent:"Update the charge master and clinical favourites lists with the annual code set, and audit for deleted codes in the first week of January rather than discovering them through denials in March.",service:"medical-coding"},{code:"CO-182",slug:"co-182",recover:"clerical",title:"Procedure modifier invalid on the date of service",short:"Modifier invalid on that date",official:"Procedure modifier was invalid on the date of service.",plain:"The modifier attached to the code was not valid on the day of the service.",causes:["Modifier retired or redefined in the annual update","A payer-specific modifier used with a payer that does not recognize it","A modifier valid for a different code category applied to this one","Modifier appended by a rule in the billing system that was never reviewed after an update"],fix:["Check the modifier against the rules in force on the date of service and against that payer’s own guidance.","Remove or replace it and resubmit corrected — do not simply strip modifiers to make a claim pay, because that changes what you are asserting.","Where an automated rule appended it, fix the rule; otherwise the same denial arrives every day."],prevent:"Review automated modifier rules against the annual update. A rule written for last year’s guidance keeps firing silently.",service:"medical-coding"},{code:"CO-183",slug:"co-183",recover:"enrollment",title:"Referring provider not eligible to refer",short:"Referring provider not eligible",official:"The referring provider is not eligible to refer the service billed.",plain:"Somebody is named as the referring provider who the payer will not accept in that role.",causes:["Referring provider not enrolled with the payer, or enrollment lapsed","NPI wrong or belonging to a different provider","Provider type not permitted to refer this service under the payer’s rules","Referring provider field populated with the rendering provider by default"],fix:["Verify the referring provider’s NPI against the national registry and the payer’s enrollment file.","Where the enrollment has lapsed, that is the referring practice’s problem to fix and yours to chase — the claim will not pay until it is.","Correct the NPI and resubmit corrected where it was a data error.","For Medicare-family denials, check the ordering and referring file specifically rather than assuming general enrollment covers it."],prevent:"Validate referring NPIs at intake rather than at billing, and re-validate for any referrer whose claims have denied before.",service:"credentialing"},{code:"CO-184",slug:"co-184",recover:"enrollment",title:"Ordering provider not eligible to order or prescribe",short:"Ordering provider not eligible",official:"The prescribing/ordering provider is not eligible to prescribe/order the service billed.",plain:"The provider named as ordering the service is not accepted by the payer in that role.",causes:["Ordering provider not enrolled, or enrollment deactivated after a missed revalidation","NPI incorrect on the order","Provider type not permitted to order this category of service","A supervising physician named where the payer requires the ordering one, or the reverse"],fix:["Check the ordering provider’s enrollment status with that payer directly, and their revalidation date where it is a Medicare-family denial.","Correct the NPI where it is wrong and resubmit corrected.","Where enrollment has lapsed, chase it — the claim will keep denying until it is restored, and the restoration date matters for whether the claim can be reprocessed."],prevent:"Track revalidation dates for every provider who orders for you, not just the ones who bill. A deactivation nobody was watching denies every downstream claim.",service:"credentialing"},{code:"CO-226",slug:"co-226",recover:"supply",title:"Requested information from the provider not supplied",short:"Requested information not supplied",official:"Information requested from the Billing/Rendering Provider was not provided or not provided timely or was insufficient/incomplete. At least one Remark Code must be provided (may be comprised of either the NCPDP Reject Reason Code, or Remittance Advice Remark Code that is not an ALERT.)",plain:"The payer asked you for something, and either nothing arrived or what arrived did not answer the question.",causes:["A records or information request that never reached the person who could answer it","Documentation sent that did not address what was actually asked","Request answered after the payer’s deadline","Response sent to the wrong address, fax or portal"],fix:["Find the original request and read exactly what was asked — most failed responses answered a different question.","Send what was asked, in the channel the payer specified, and record the confirmation.","Where the deadline has passed, ask what the reconsideration route is and its window.","Log the request, the response and the confirmation on the account so a second request does not start from nothing."],prevent:"Treat payer information requests as a tracked queue with a due date, not as post. This denial is a process failure inside the practice almost every time.",service:"ar-calling-denial-management"},{code:"CO-227",slug:"co-227",recover:"supply",title:"Requested information from the patient not supplied",short:"Patient did not supply information",official:"Information requested from the patient/insured/responsible party was not provided or was insufficient/incomplete. At least one Remark Code must be provided (may be comprised of either the NCPDP Reject Reason Code, or Remittance Advice Remark Code that is not an ALERT.)",plain:"The payer asked the patient for something — very often about other insurance or an accident — and did not get it.",causes:["Coordination of benefits questionnaire sent to the patient and not returned","Accident or injury details requested and not supplied","Student or dependent status verification outstanding","Payer wrote to an old address"],fix:["Ring the payer and find out exactly what was asked of the patient and how they can supply it.","Contact the patient and tell them specifically what to do — most of these sit unanswered because the payer’s letter was not understood.","Many payers will accept the information over the phone from the patient, which is far faster than post.","Resubmit or ask for reprocessing once the payer confirms it has what it needs."],prevent:"Ask about other coverage and about accident-related care at registration. A coordination of benefits question answered on day one never becomes this denial.",service:"patient-billing"},{code:"CO-242",slug:"co-242",recover:"enrollment",title:"Services not provided by network providers",short:"Provider out of network",official:"Services not provided by network/primary care providers.",plain:"The plan pays only for its own network, and this provider was not in it for this service.",causes:["Provider not contracted with this plan, as opposed to not contracted with this payer","Contract in place with the payer but not with the specific product the patient holds","Credentialing complete but the effective date after the service","Patient in a narrow-network or exchange product the practice does not participate in"],fix:["Confirm participation for the specific plan and product, not just the payer name. In our experience this distinction accounts for most of these denials.","Check the contract effective date against the date of service.","Where participation exists and the payer’s file is wrong, escalate to provider relations with the contract — and ask for reprocessing of every affected claim, not just this one.","Where the practice genuinely is out of network, check what the patient was told before the visit before any balance moves."],prevent:"Verify plan-level participation at eligibility. A payer contract does not mean every product under that payer’s name.",service:"credentialing"},{code:"CO-251",slug:"co-251",recover:"supply",title:"Attachment or documentation incomplete or deficient",short:"Documentation incomplete",official:"The attachment/other documentation that was received was incomplete or deficient. The necessary information is still needed to process the claim. At least one Remark Code must be provided (may be comprised of either the NCPDP Reject Reason Code, or Remittance Advice Remark Code that is not an ALERT).",plain:"Something was sent, and it did not contain what the payer needed.",causes:["Partial record sent — the note without the order, or the order without the result","Illegible scan or a fax that arrived unreadable","Wrong date of service supplied","Signature or credentials missing from the documentation"],fix:['Ask the payer specifically what was deficient. "Incomplete" is not actionable; the missing element is.',"Resend the complete set, legible, with the claim and patient identifiers on every page.","Confirm receipt and record the reference number — documentation lost in transit is common and unprovable without it.","Where the record genuinely lacks a required element, that is a documentation query to the provider, not something billing can supply."],prevent:"Build a per-payer checklist of what a records request has to include for the common review types, and check it before sending rather than after a denial.",service:"ar-calling-denial-management"},{code:"CO-253",slug:"co-253",recover:"contractual",title:"Sequestration reduction in federal payment",short:"Sequestration reduction",official:"Sequestration - reduction in federal payment.",plain:"A statutory percentage reduction applied to a federal payment. It is not a denial and there is nothing to appeal.",causes:["The mandatory federal payment reduction applied to Medicare fee-for-service payments","Appears as a separate adjustment line on the remittance alongside the payment"],fix:["Post it as an adjustment. There is no appeal and no correction — it is a statutory reduction, not a determination about your claim.","Read the group code: this is not patient responsibility and must not be billed to the patient.","Where a posting rule is treating it as a balance to pursue, fix the rule — staff time spent chasing sequestration is entirely wasted."],prevent:"Map this adjustment to an automatic contractual adjustment in posting so it never reaches a work queue. [VERIFY] The reduction percentage is set by federal law and has been suspended and reinstated before — confirm the rate currently in force rather than relying on a figure from a previous year.",service:"payment-posting"},{code:"CO-256",slug:"co-256",recover:"contractual",title:"Service not payable under the managed care contract",short:"Not payable under the contract",official:"Service not payable per managed care contract.",plain:"The managed care contract in force does not provide for payment of this service.",causes:["Service excluded from the contract’s covered list","Service carved out to a different vendor — behavioural health, vision, laboratory and radiology are the usual carve-outs","Contract requires the service to be delivered by a designated provider","Billed to the plan when the capitated group holds the risk"],fix:["Read the contract’s covered services and carve-outs before appealing. Most of these are correct denials sent to the wrong entity.","Where the service is carved out, bill the carve-out vendor inside its own filing window.","Where the contract does cover it, appeal with the contract language cited specifically.","Read the group code before any balance is moved to the patient."],prevent:"Keep a per-contract summary of carve-outs where billing can see it. Carve-outs are invisible on an eligibility check and are the usual reason for this denial.",service:"ar-calling-denial-management"},{code:"CO-272",slug:"co-272",recover:"auth-late",title:"Coverage or program guidelines not met",short:"Coverage guidelines not met",official:"Coverage/program guidelines were not met.",plain:"The service is covered in principle but this instance did not meet the programme’s conditions.",causes:["Frequency limit exceeded — the service is covered but not this often","A required prior step not documented, such as a conservative treatment period","Coverage determination criteria not met for the diagnosis billed","A required screening interval not yet elapsed"],fix:["Get the specific guideline that was not met from the payer, in writing where the amount justifies it.","Check the frequency history — a service delivered elsewhere counts, and the practice usually cannot see it.","Where prior conservative treatment exists in the record, appeal with those dates documented.","Where the criteria genuinely were not met, the conversation is with the provider about the pathway, not with the payer."],prevent:"For services with frequency limits or step requirements, check the history at scheduling. This denial is almost always knowable before the visit.",service:"prior-authorization"},{code:"CO-B10",slug:"co-b10",recover:"contractual",title:"Allowed amount reduced — a component of the procedure was already paid",short:"Component already paid",official:"Allowed amount has been reduced because a component of the basic procedure/test was paid. The beneficiary is not liable for more than the charge limit for the basic procedure/test.",plain:"The payer paid part of this procedure on another line or claim and has reduced this one to the difference, so the practice is not paid twice for the same work.",causes:["A component code (a technical or professional part, a base test) billed on its own and then the complete procedure billed as well","The same procedure reported on two claims for the same date — one from the facility, one from the physician — where only one is payable in full","Bundled services reported separately when the payer’s edit pays the comprehensive code and reduces the parts"],fix:["Find the earlier payment: pull every line paid for this patient on this date and identify the component the payer says it already covered.","If the earlier line was the wrong code, correct that claim rather than appealing this reduction — the reduction is arithmetic, and it follows the coding.","If both services were genuinely distinct, this is a coding appeal with the operative or test report showing two separate procedures, and the modifier that says so.","Do not bill the patient for the reduced amount. The code says the beneficiary is not liable for more than the charge limit for the basic procedure."],prevent:"Run comprehensive-and-component checks in the scrubber so a base procedure and its parts cannot leave on separate lines without a modifier that justifies it.",service:"medical-coding"},{code:"CO-273",slug:"co-273",recover:"clinical",title:"Coverage or program guidelines exceeded",short:"Guidelines exceeded",official:"Coverage/program guidelines were exceeded.",plain:"The service is covered, but this instance went past a programme limit: more visits, units or sessions than the guideline allows.",causes:["A visit or unit count above the plan’s annual or per-episode limit","A course of treatment continued beyond the authorised number of sessions","A frequency limit on a test or a screening reached earlier in the year, often at another provider","A level of service above what the programme covers for the diagnosis"],fix:["Ask the payer which guideline and which limit — the number, the period, and how many units they count as used — in writing where the amount justifies it.","Check the history across providers where you can: a limit reached elsewhere still counts against this patient.","If the extra services were medically necessary, appeal with the record showing why the guideline should be exceeded for this patient; most programmes have an exceptions process.","If the limit is genuinely exhausted, the remaining balance follows the plan document — some make it patient responsibility with notice, some do not — and the conversation is with the patient before the next visit, not after."],prevent:"Track authorised units and plan limits per patient in the scheduling system so the visit that would exceed the guideline is flagged before it is booked.",service:"prior-authorization"},{kind:"rarc",code:"N130",slug:"n130",recover:"coverage",title:"Consult plan benefit documents for restrictions",short:"Check the plan benefit documents",official:"Consult plan benefit documents/guidelines for information about restrictions for this service.",plain:"The payer is pointing you at the plan document: there is a restriction on this service and the document says what it is.",causes:["A plan-level limitation — frequency, quantity, site of service or a specific exclusion","A benefit that requires a condition to be met before it pays","Accompanying a denial or reduction that the CARC on the same line explains"],fix:["Read the CARC on the same line first. The remark explains; the reason code is what actually happened.","Get the specific restriction from the payer rather than the general benefit document, and record it against the payer on the account.","Where the restriction was met and the payer applied it wrongly, appeal citing the plan language."],prevent:"Keep a per-payer note of restrictions you have already been told about. This remark tends to arrive repeatedly for the same service and the same plan.",service:"ar-calling-denial-management"},{kind:"rarc",code:"N382",slug:"n382",recover:"clerical",title:"Missing, incomplete or invalid patient identifier",short:"Patient identifier invalid",official:"Missing/incomplete/invalid patient identifier.",plain:"The payer cannot match the patient from what was sent.",causes:["Member ID transposed, or missing a required alpha prefix","Name on the claim differs from the name on the policy","Date of birth mismatch","Old member ID used after the payer reissued cards"],fix:["Run eligibility and take the identifier exactly as the payer returns it, including any prefix or suffix.","Compare name and date of birth character by character against the payer record, not against the chart.","Correct and resubmit. This is a claim that was never processed, so it is a resubmission rather than an appeal.","Check the timely filing window — unprocessable claims still age."],prevent:"Capture the identifier from an eligibility response rather than from a photocopied card, and re-verify after any plan year change.",service:"eligibility-verification"},{kind:"rarc",code:"MA130",slug:"ma130",recover:"clerical",title:"Claim unprocessable — no appeal rights",short:"Unprocessable, no appeal rights",official:"Your claim contains incomplete and/or invalid information, and no appeal rights are afforded because the claim is unprocessable. Please submit a new claim with the complete/correct information.",plain:"The claim was rejected as unprocessable rather than denied. There is nothing to appeal — it has to be corrected and sent again as a new claim.",causes:["A required field missing or invalid — provider identifiers, diagnosis, dates","Invalid or deleted code","Formatting or data problems that stop the claim being adjudicated at all"],fix:["Do not file an appeal. There are no appeal rights on an unprocessable claim and the time spent is lost.","Find the accompanying remark codes — they name the specific fields at fault.","Correct and submit as a NEW claim, not a corrected one, because the original was never adjudicated.","Check the timely filing window immediately: unprocessable claims consume it exactly like any other."],prevent:"Front-end edits are what stop this. A claim that fails a scrub costs minutes; one that returns unprocessable costs a cycle and can cost the filing window.",service:"charge-entry"},{kind:"rarc",code:"N29",slug:"n29",recover:"supply",title:"Missing documentation, orders, notes or report",short:"Documentation missing",official:"Missing documentation/orders/notes/summary/report/chart.",plain:"The payer needs clinical documentation it does not have.",causes:["Records request outstanding","A service requiring an order where the order was not supplied","Documentation sent without the specific element the payer wanted","Attachment did not link to the claim on the payer’s side"],fix:["Establish exactly what document is wanted, for which date of service, and in which channel.","Send it with claim and patient identifiers on every page, and record the confirmation reference.","Where an order is required and does not exist, this is a documentation problem for the provider — billing cannot create an order after the fact."],prevent:"For service categories that routinely attract records requests, attach the documentation at submission where the payer accepts it.",service:"ar-calling-denial-management"},{kind:"rarc",code:"N30",slug:"n30",recover:"coverage",title:"Patient ineligible for this service",short:"Patient ineligible for this service",official:"Patient ineligible for this service.",plain:"The patient does not qualify for this particular service under their plan, even though they may hold coverage.",causes:["A benefit the patient’s plan does not include","Eligibility criteria for the specific service not met","Service restricted to a category the patient does not fall into","Coverage active but the benefit not effective"],fix:["Read the CARC on the same line — the remark explains, the reason code determines the outcome.","Confirm the benefit specifically, not the coverage generally, for the date of service.","Where there is secondary coverage carrying the benefit, bill it inside its filing window.","Read the group code before any balance moves to the patient."],prevent:'Verify the specific benefit before high-cost or elective services. "Active coverage" answers a different question from "is this service covered".',service:"eligibility-verification"},{kind:"rarc",code:"N34",slug:"n34",recover:"clerical",title:"Incorrect claim form or format for this service",short:"Wrong claim form or format",official:"Incorrect claim form/format for this service.",plain:"The service was billed on the wrong form or in the wrong format for the payer.",causes:["Professional service billed institutionally, or the reverse","A service that payer requires on a specific form or transaction type","Wrong bill type on an institutional claim","Paper submitted where the payer requires electronic"],fix:["Confirm which form and which bill type that payer requires for this service.","Resubmit in the correct format. This is a new submission rather than an appeal, because the claim was never properly received.","Where the billing system chose the format automatically, fix the rule — otherwise every claim of this type repeats it."],prevent:"Record per-payer form requirements for services that can be billed either way. It is a small list and it prevents an entire denial category.",service:"charge-entry"},{kind:"rarc",code:"N54",slug:"n54",recover:"auth-late",title:"Claim inconsistent with the authorized services",short:"Claim does not match the authorization",official:"Claim information is inconsistent with pre-certified/authorized services.",plain:"There is an authorization, and what was billed does not match what it covers.",causes:["Procedure performed differs from the one authorized","Units or visits billed exceed those authorized","Date of service outside the authorized range","Rendering provider or facility different from the one named on the authorization"],fix:["Put the authorization and the claim side by side and compare code, provider, facility, dates and units. One will differ.","Where the service legitimately changed in theatre or in the room, ask the payer about a retro-authorization or an amendment and document the clinical reason.","Where it is a billing error, correct and resubmit corrected.","Where units were exceeded, the excess is usually not recoverable — the lesson is the count, not the appeal."],prevent:"Check the authorization against the plan before the service and against the claim before submission. Two checks, both cheap, and they remove this category.",service:"prior-authorization"},{kind:"rarc",code:"N115",slug:"n115",recover:"clinical",title:"Decision based on a Local Coverage Determination",short:"Decided by a local coverage policy",official:"This decision was based on a Local Coverage Determination (LCD). An LCD provides a guide to assist in determining whether a particular item or service is covered. A copy of this policy is available at www.cms.gov/mcd, or if you do not have web access, you may contact the contractor to request a copy of the LCD.",plain:"A published coverage policy for your region decided this, and that policy states exactly what would have been covered.",causes:["Diagnosis billed not on the policy’s covered list","Frequency or documentation requirements in the policy not met","Service considered not reasonable and necessary for the indication under that policy"],fix:["Find and read the actual policy. It lists the covered diagnoses and the documentation required, which makes this one of the most answerable denials there is.","Where the record supports a covered indication that was not billed, correct the coding to match the record — never to match the policy.","Where the documentation requirements were met, appeal citing the policy’s own criteria point by point.","Where they were not met, an advance beneficiary notice before the service is the mechanism, not an appeal afterwards."],prevent:"For services covered by a determination in your region, check the policy at scheduling. The requirements are published and specific, which is unusual and useful.",service:"medical-coding"},{kind:"rarc",code:"N122",slug:"n122",recover:"clinical",title:"Add-on code cannot be billed by itself",short:"Add-on code billed alone",official:"Add-on code cannot be billed by itself.",plain:"The code billed only exists alongside a primary procedure, and no acceptable primary was on the claim.",causes:["Primary procedure omitted from the claim","Primary procedure billed on a separate claim or a different date","Primary procedure denied, taking the add-on with it","Add-on billed with a primary that is not one of its permitted primaries"],fix:["Check whether the primary procedure was billed at all, and on which claim.","Where both were performed and billed separately, resubmit them together on one claim.","Where the primary denied, resolve that first — the add-on cannot pay while the primary does not.","Confirm the add-on is permitted with the primary you billed; the permitted pairings are defined and not interchangeable."],prevent:"Where an add-on exists in the charge master, pair it with its permitted primaries in the scrub rules so it cannot leave the building alone.",service:"medical-coding"},{kind:"rarc",code:"N362",slug:"n362",recover:"clerical",title:"Units of service exceed the payer’s maximum",short:"Units over the maximum",official:"The number of Days or Units of Service exceeds our acceptable maximum.",plain:"The line carries more units than the payer allows for that code on one date, so it rejected the quantity rather than the service.",causes:["Units billed against the wrong unit definition — a drug billed per vial when the HCPCS code is per milligram, or a timed code billed in minutes instead of 15-minute units","The same service split across lines so the units add up past the limit","A Medicare medically unlikely edit (MUE) or a commercial frequency limit on the code","A quantity typed with an extra digit"],fix:["Read the code’s unit definition and recount. Most of these are a units error, and a corrected claim with the right quantity pays.","If the units are right and the service was needed, this is an appeal with documentation — the note has to show why this patient needed that many on that day.","For Medicare, check the MUE value and its adjudication indicator for the code: a line-level edit can be answered by reporting clinically distinct units on separate lines with the right modifier; a date-of-service edit cannot."],prevent:"Load unit definitions and payer maximums into the charge scrubber so an over-limit quantity is caught before the claim leaves.",service:"medical-coding"},{kind:"rarc",code:"N381",slug:"n381",recover:"contractual",title:"Adjusted per the contract — read the contract",short:"Per contract",official:"Alert: Consult our contractual agreement for restrictions/billing/payment information related to these charges.",plain:"An alert, not a denial: the payer processed the line under your contract and is pointing you at it. The reason code beside it carries the money.",causes:["A contracted rate lower than the charge — the difference posts as a contractual adjustment","A contract term that bundles this service into another, or excludes it","A reduction for a multiple-procedure or site-of-service rule written into the agreement","A payer applying a contract you do not have — the wrong fee schedule, or a terminated one"],fix:["Compare the allowed amount with the contracted rate for this code, this provider, this date. At or above the contract, post the adjustment and move on.","Below the contract, it is an underpayment: dispute it with the contract page and the rate cited, through the payer’s reconsideration route — not an appeal about medical necessity.","If you have no contract with this payer, ask which agreement they are applying; a rental network or a wrong provider record is the usual answer."],prevent:"Keep every payer contract’s fee schedule loaded where the posting team can see it, so a contractual adjustment is compared, not assumed.",service:"underpayment-recovery"},{kind:"rarc",code:"N522",slug:"n522",recover:"coverage",title:"Duplicate of a crossover claim",short:"Crossover duplicate",official:"Duplicate of a claim processed, or to be processed, as a crossover claim.",plain:"The secondary payer already has this claim — Medicare forwarded it automatically — and the copy you sent is the duplicate.",causes:["The claim was billed to the secondary directly while Medicare’s crossover was still in flight","The patient’s supplemental plan is on file with Medicare for automatic crossover, and the office bills secondaries by hand","A corrected claim sent to the secondary without waiting for the crossover copy to adjudicate"],fix:["Do nothing to this claim. Find the crossover copy — the Medicare remittance carries MA18 when it forwarded the claim — and post from the secondary’s remittance when that copy adjudicates.","If the crossover copy never appears after a reasonable wait, bill the secondary with the Medicare remittance attached and say in the claim notes that no crossover was received.","Stop manual secondary billing for patients whose supplemental plan crosses over automatically; the Medicare remittance tells you which ones."],prevent:"Flag crossover patients in the practice management system and route their secondaries to a hold queue that waits for the crossover remittance.",service:"payment-posting"},{kind:"rarc",code:"MA30",slug:"ma30",recover:"clerical",title:"Missing, incomplete or invalid type of bill",short:"Type of bill invalid",official:"Missing/incomplete/invalid type of bill.",plain:"A facility claim problem: the three-digit type of bill in field 4 of the UB-04 does not fit the facility, the claim, or the frequency.",causes:["The frequency digit is wrong — an original (1) sent for what should be a replacement (7) or a void (8)","A type of bill that does not match the facility type enrolled with the payer","A field left blank, or carrying a leading zero the payer does not accept","A professional claim format sent for a service the payer wants on an institutional claim, or the reverse"],fix:["Read the payer’s billing guide for the facility type and set field 4 to the type of bill it names, with the right frequency digit.","Resubmit. If the payer already has the original on file, the resubmission is a replacement — frequency 7 — not another original, or you collect a duplicate denial next.","If the payer wants the service on a different claim form altogether, that is a setup problem in the billing system, not a one-off correction."],prevent:"Lock the type of bill per facility and service line in the billing system so it is selected, not typed.",service:"charge-entry"},{kind:"rarc",code:"N830",slug:"n830",recover:"contractual",title:"Processed under surprise-billing rules — the patient cannot be balance billed",short:"No Surprises Act",official:"Alert: The charge[s] for this service was processed in accordance with Federal/ State, Balance Billing/ No Surprise Billing regulations. As such, any amount identified with OA, CO, or PI cannot be collected from the member and may be considered provider liability or be billable to a subsequent payer. Any amount the provider collected over the identified PR amount must be refunded to the patient within applicable Federal/State timeframes. Payment amounts are eligible for dispute pursuant to any Federal/State documented appeal/grievance process(es).",plain:"An out-of-network service the payer processed under federal or state surprise-billing rules: the patient owes only the PR amount, and any dispute over the payment is with the payer, not the patient.",causes:["Emergency services, or non-emergency services at an in-network facility, furnished out of network","A state balance-billing law applied to a state-regulated plan","The payer paid a qualifying payment amount or a state-set rate the provider considers low"],fix:["Post the patient responsibility exactly as shown and refund anything collected above it. Balance billing here is prohibited, and the remittance says so in the code.","If the payment is too low, the route is the payer: open negotiation within the federal window, then independent dispute resolution if it fails — or the state process where a state law applies. It is not a patient statement and it is not a standard appeal.","Check whether the service was actually in scope of the rules; a payer applying them to a service outside them is a dispute in itself."],prevent:"Give the posting team one rule: any line with N830 is patient-liability-locked, and anything above PR goes to the disputes queue with a deadline on it.",service:"underpayment-recovery"},{kind:"rarc",code:"M115",slug:"m115",recover:"enrollment",title:"Denied — not a contract supplier for this item",short:"Non-contract supplier",official:"This item is denied when provided to this patient by a non-contract or non-demonstration supplier.",plain:"A DMEPOS competitive bidding denial: for this item, in this area, Medicare pays only suppliers holding a contract, and this claim came from one that does not.",causes:["The item falls in a competitively bid product category for the patient’s area and the supplier holds no contract for it","The patient moved into a competitive bidding area and the supplier did not check","A grandfathering or demonstration exception that applies but was not claimed on the claim"],fix:["Check the current status of the Competitive Bidding Program for the product category and the patient’s ZIP code on the CMS DMEPOS competitive bidding site before anything else — rounds start and end, and the answer changes with them.","If the program applies and you are not a contract supplier, the claim is not payable to you; the patient must obtain the item from a contract supplier, and any signed notice you hold decides whether the patient can be billed.","If an exception applies — a grandfathered rental, a demonstration — resubmit with the modifier or documentation the exception requires."],prevent:"Verify the patient’s address against the competitive bidding areas at intake for every bid-category item, and keep the program’s round dates on the DME desk’s calendar.",service:"dme-billing"},{kind:"rarc",code:"MA27",slug:"ma27",recover:"clerical",title:"Missing, incomplete or invalid Medicare number or name",short:"Medicare number or name invalid",official:"Missing/incomplete/invalid entitlement number or name shown on the claim.",plain:"Medicare cannot match the beneficiary: the Medicare Beneficiary Identifier or the name on the claim does not agree with the entitlement record.",causes:["The old HICN, or a mistyped MBI","Name entered as it appears in the chart rather than exactly as on the Medicare card — a middle initial, a hyphen, a suffix","A new MBI issued after the card was compromised, with the office still using the old one"],fix:["Run a Medicare eligibility check and take the MBI and name exactly as returned; the MAC portals also offer an MBI lookup.","Correct the claim and resubmit. It was returned unprocessable, so there is nothing to appeal.","Watch the timely filing clock — an unprocessable claim does not stop it."],prevent:"Capture the MBI from an eligibility response at every visit, not from the card image, and re-check when a card is reported lost.",service:"eligibility-verification"},{kind:"rarc",code:"M51",slug:"m51",recover:"clerical",title:"Missing, incomplete or invalid procedure code",short:"Procedure code invalid",official:"Missing/incomplete/invalid procedure code(s).",plain:"The code on the line is not one the payer recognises for that date: deleted, mistyped, or from the wrong code set.",causes:["A CPT or HCPCS code deleted or replaced at the last update and still in the charge master","A code from the wrong set — a payer-specific HCPCS where the payer wants CPT, or a Category III code the payer does not accept","A transposed digit, or a code left blank on an added line","A code valid on the date of service but billed against a different date"],fix:["Validate the code against the code set in force on the date of service, then resubmit as a corrected claim with the right one.","If the code was replaced, map the old code to its successor in the charge master before the next claim goes out, or this repeats every day.","Read the remark beside it — M51 with a payer-specific note usually names the code set they want."],prevent:"Run the annual CPT and HCPCS deletions against the charge master every January, and the quarterly HCPCS updates, before the first claim of the period.",service:"medical-coding"},{kind:"rarc",code:"N4",slug:"n4",recover:"coverage",title:"Missing or invalid primary payer explanation of benefits",short:"Primary EOB missing",official:"Missing/Incomplete/Invalid prior Insurance Carrier(s) EOB.",plain:"The secondary payer will not adjudicate without the primary payer’s decision: what was allowed, paid and adjusted, line by line.",causes:["A secondary claim sent without the primary remittance data — no coordination-of-benefits loops on the 837, no EOB attached on paper","Primary payment posted as a lump sum, so the line-level amounts the secondary needs were never captured","The primary payer’s adjudication attached is for a different date or claim","The order of coverage is wrong — the plan billed as secondary is actually primary"],fix:["Send the secondary claim with the primary’s adjudication carried in the claim itself: allowed, paid and adjustment amounts with their group and reason codes, per line.","If it went on paper, attach the primary remittance page that shows this claim, not the whole remittance.","Confirm the order of coverage with both payers before resubmitting; a wrong order produces this code on every claim."],prevent:"Post primary remittances at line level from the 835, so the secondary claim can be built from data rather than from a scanned page.",service:"payment-posting"},{kind:"rarc",code:"N290",slug:"n290",recover:"clerical",title:"Missing, incomplete or invalid rendering provider identifier",short:"Rendering provider NPI invalid",official:"Missing/incomplete/invalid rendering provider primary identifier.",plain:"The NPI of the clinician who performed the service is missing from the claim, is not a valid NPI, or is not one the payer has linked to your group.",causes:["Rendering NPI left blank when it differs from the billing NPI, or the group NPI entered in its place","An individual NPI the payer has not enrolled or linked to the billing group","A new hire seeing patients before enrollment with this payer was complete","A typed NPI with a wrong check digit"],fix:["Check the NPI against the NPPES registry and put the individual’s NPI in the rendering provider field, with the group NPI as billing provider.","If the NPI is right, this is enrollment: confirm with the payer that the clinician is enrolled and linked to the group for that date of service, and rebill once the link is effective.","Where the effective date is after the date of service, ask the payer about retroactive enrollment before writing anything off; some allow it."],prevent:"Do not schedule a new clinician for a payer’s patients until that payer confirms the enrollment and the group link in writing.",service:"credentialing"}]])}]);